import { useLayoutEffect } from "react";

/**
 * 路由切换时对当前页面做一次 reveal-in 扫描。
 *
 * 不用 MutationObserver 全程盯 body：SPA 内部状态变化（切换命令组、搜索过滤等）
 * 会替换大量 DOM，observer 会把新节点误判成"待揭示元素"，导致闪烁和 class 错位。
 * reveal 只在 pathname 变化时跑一次，之后的动态内容直接可见。
 */
export function useScrollReveal(routeKey: string, motionEnabled: boolean) {
  useLayoutEffect(() => {
    const elements = Array.from(document.querySelectorAll<HTMLElement>(".reveal-in"));
    if (elements.length === 0) return;

    if (!motionEnabled || !("IntersectionObserver" in window)) {
      elements.forEach((el) => {
        el.classList.add("is-visible");
        el.classList.remove("reveal-pending");
      });
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          const el = entry.target as HTMLElement;
          el.classList.add("is-visible");
          el.classList.remove("reveal-pending");
          observer.unobserve(el);
        });
      },
      { rootMargin: "0px 0px -8%", threshold: 0.08 },
    );

    elements.forEach((el) => {
      if (el.classList.contains("is-visible")) return;
      el.classList.add("reveal-pending");
      observer.observe(el);
    });

    return () => {
      observer.disconnect();
      elements.forEach((el) => el.classList.remove("reveal-pending"));
    };
  }, [motionEnabled, routeKey]);
}
