import { Check, LoaderCircle, Play } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { usePreferences } from "../hooks/usePreferences";

const initialLines = [
  { kind: "command", value: "hyx doctor" },
  { kind: "output", value: "[ok] workspace ........ hongyunx-agent" },
  { kind: "output", value: "[ok] model route ...... ready" },
  { kind: "output", value: "[ok] session store .... sqlite" },
  { kind: "command", value: "hyx chat \"review this patch\"" },
  { kind: "output", value: "agent / coding · tools / 12 · stream / active" },
];

type RunState = "idle" | "running" | "success";

export function TerminalDemo() {
  const { t } = useTranslation();
  const { motionEnabled } = usePreferences();
  const [command, setCommand] = useState("hyx doctor");
  const [lines, setLines] = useState(initialLines);
  const [runState, setRunState] = useState<RunState>("idle");
  const timerRef = useRef<number | null>(null);

  useEffect(() => () => {
    if (timerRef.current) window.clearTimeout(timerRef.current);
  }, []);

  const runCommand = (event: React.FormEvent) => {
    event.preventDefault();
    const nextCommand = command.trim();
    if (!nextCommand || runState === "running") return;
    if (timerRef.current) window.clearTimeout(timerRef.current);
    setRunState("running");
    setLines((current) => [...current.slice(-4), { kind: "command", value: nextCommand }]);
    timerRef.current = window.setTimeout(() => {
      setLines((current) => [...current, { kind: "output", value: `[ok] ${t("terminal.simulated")} · 128ms` }]);
      setRunState("success");
      timerRef.current = window.setTimeout(() => setRunState("idle"), motionEnabled ? 1600 : 250);
    }, motionEnabled ? 720 : 80);
  };

  return (
    <div className="terminal-demo" aria-label={t("terminal.label")}>
      <div className="terminal-demo__bar">
        <span className="traffic traffic--red" />
        <span className="traffic traffic--amber" />
        <span className="traffic traffic--green" />
        <span>hyx://workspace/hongyunx-agent</span>
      </div>
      <div className="terminal-demo__body">
        {lines.map((line, index) => (
          <div className={`terminal-line terminal-line--${line.kind}`} style={{ animationDelay: motionEnabled ? `${Math.min(index, 5) * 90}ms` : "0ms" }} key={`${line.value}-${index}`}>
            {line.kind === "command" ? <span className="terminal-prompt">➜</span> : null}
            <span>{line.value}</span>
          </div>
        ))}
        {runState === "running" ? <div className="terminal-progress"><span /><span /><span /></div> : <div className="terminal-cursor" aria-hidden="true" />}
      </div>
      <form className="terminal-demo__runner" onSubmit={runCommand}>
        <span className="terminal-prompt">$</span>
        <input value={command} onChange={(event) => setCommand(event.target.value)} aria-label={t("terminal.commandPlaceholder")} />
        <button type="submit" disabled={runState === "running"} aria-label={t("terminal.run")} title={t("terminal.run")}>
          {runState === "running" ? <LoaderCircle className="spin" size={15} /> : runState === "success" ? <Check size={15} /> : <Play size={15} />}
        </button>
      </form>
      <div className="terminal-demo__status" aria-live="polite">
        <span>CORE ENGINE · {t("terminal.simulated")}</span>
        <b className={`run-status run-status--${runState}`}><i /> {t(`terminal.${runState}`)}</b>
      </div>
    </div>
  );
}
