function revealDelay(delayMs: number) {
  return { "--reveal-delay": `${delayMs}ms` } as CSSProperties;
}

function useInViewOnce(enabled: boolean) {
  const ref = useRef<HTMLElement | null>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    if (!enabled) return;
    const node = ref.current;
    if (!node || typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver((entries) => {
      if (entries.some((entry) => entry.isIntersecting)) {
        setInView(true);
        observer.disconnect();
      }
    }, { threshold: 0.35 });
    observer.observe(node);
    return () => observer.disconnect();
  }, [enabled]);

  return { ref, inView: !enabled || inView };
}

function CountUp({ target, active }: { target: number; active: boolean }) {
  if (!active) return <>{target}</>;
  return <CountUpTicker target={target} />;
}

function CountUpTicker({ target }: { target: number }) {
  const [display, setDisplay] = useState(0);

  useEffect(() => {
    let frame = 0;
    const startedAt = performance.now();
    const duration = 1150;
    const tick = (now: number) => {
      const progress = Math.min(1, (now - startedAt) / duration);
      const eased = 1 - Math.pow(1 - progress, 3);
      setDisplay(Math.round(target * eased));
      if (progress < 1) frame = window.requestAnimationFrame(tick);
    };
    frame = window.requestAnimationFrame(tick);
    return () => window.cancelAnimationFrame(frame);
  }, [target]);

  return <>{display}</>;
}

function useStageTilt(enabled: boolean) {
  const ref = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const node = ref.current;
    if (!enabled || !node) return;
    let frame = 0;
    const handleMove = (event: PointerEvent) => {
      if (frame) return;
      frame = window.requestAnimationFrame(() => {
        const rect = node.getBoundingClientRect();
        const x = (event.clientX - rect.left) / rect.width - 0.5;
        const y = (event.clientY - rect.top) / rect.height - 0.5;
        node.style.setProperty("--stage-ry", `${(x * 5).toFixed(2)}deg`);
        node.style.setProperty("--stage-rx", `${(-y * 5).toFixed(2)}deg`);
        node.style.setProperty("--stage-px", x.toFixed(3));
        node.style.setProperty("--stage-py", y.toFixed(3));
        frame = 0;
      });
    };
    const handleLeave = () => {
      if (frame) {
        window.cancelAnimationFrame(frame);
        frame = 0;
      }
      node.style.setProperty("--stage-ry", "0deg");
      node.style.setProperty("--stage-rx", "0deg");
      node.style.setProperty("--stage-px", "0");
      node.style.setProperty("--stage-py", "0");
    };
    node.addEventListener("pointermove", handleMove);
    node.addEventListener("pointerleave", handleLeave);
    return () => {
      node.removeEventListener("pointermove", handleMove);
      node.removeEventListener("pointerleave", handleLeave);
      if (frame) window.cancelAnimationFrame(frame);
    };
  }, [enabled]);

  return ref;
}

function useScrollDepth(enabled: boolean) {
  useEffect(() => {
    if (!enabled) return;
    let frame = 0;
    const update = () => {
      frame = 0;
      const hero = document.querySelector<HTMLElement>(".main-hero");
      if (!hero) return;
      const rect = hero.getBoundingClientRect();
      const span = Math.max(1, rect.height * 0.72);
      const depth = Math.min(1, Math.max(0, -rect.top / span));
      hero.style.setProperty("--hero-depth", depth.toFixed(3));
    };
    const handleScroll = () => {
      if (!frame) frame = window.requestAnimationFrame(update);
    };
    update();
    window.addEventListener("scroll", handleScroll, { passive: true });
    window.addEventListener("resize", handleScroll);
    return () => {
      window.removeEventListener("scroll", handleScroll);
      window.removeEventListener("resize", handleScroll);
      if (frame) window.cancelAnimationFrame(frame);
    };
  }, [enabled]);
}

function Magnetic({ enabled, children }: { enabled: boolean; children: ReactNode }) {
  const ref = useRef<HTMLSpanElement | null>(null);

  useEffect(() => {
    const node = ref.current;
    if (!enabled || !node) return;
    let frame = 0;
    const handleMove = (event: PointerEvent) => {
      if (frame) return;
      frame = window.requestAnimationFrame(() => {
        const rect = node.getBoundingClientRect();
        const dx = event.clientX - (rect.left + rect.width / 2);
        const dy = event.clientY - (rect.top + rect.height / 2);
        const pull = Math.max(0, 1 - Math.hypot(dx, dy) / 170);
        node.style.transform = "translate(" + (dx * 0.22 * pull).toFixed(1) + "px, " + (dy * 0.22 * pull).toFixed(1) + "px)";
        frame = 0;
      });
    };
    const handleLeave = () => {
      if (frame) {
        window.cancelAnimationFrame(frame);
        frame = 0;
      }
      node.style.transform = "";
    };
    node.addEventListener("pointermove", handleMove);
    node.addEventListener("pointerleave", handleLeave);
    return () => {
      node.removeEventListener("pointermove", handleMove);
      node.removeEventListener("pointerleave", handleLeave);
      if (frame) window.cancelAnimationFrame(frame);
    };
  }, [enabled]);

  return <span className="magnetic" ref={ref}>{children}</span>;
}

function StageCrown({ scene, count, label, valueText, onSelect }: { scene: number; count: number; label: string; valueText: string; onSelect: (index: number) => void }) {
  const step = (delta: number) => onSelect((((scene + delta) % count) + count) % count);
  return (
    <div
      className="stage-crown"
      role="slider"
      tabIndex={0}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={count - 1}
      aria-valuenow={scene}
      aria-valuetext={valueText}
      onKeyDown={(event) => {
        if (event.key === "ArrowRight" || event.key === "ArrowUp") { event.preventDefault(); step(1); }
        if (event.key === "ArrowLeft" || event.key === "ArrowDown") { event.preventDefault(); step(-1); }
      }}
      onWheel={(event) => { if (Math.abs(event.deltaY) > 6) step(event.deltaY > 0 ? 1 : -1); }}
      onClick={(event) => {
        const rect = event.currentTarget.getBoundingClientRect();
        step(event.clientX < rect.left + rect.width / 2 ? -1 : 1);
      }}
    >
      <span className="stage-crown__ring" style={{ transform: "rotate(" + scene * 90 + "deg)" }} aria-hidden="true"><i /><i /><i /><i /></span>
      <span className="stage-crown__cap" aria-hidden="true">{String(scene + 1).padStart(2, "0")}</span>
    </div>
  );
}

let cliScriptOffset = 0;
const cliConsoleScript = cliConsoleLines.map((line) => {
  const start = cliScriptOffset;
  cliScriptOffset += line.text.length;
  return { ...line, start };
});
const cliTotalChars = cliScriptOffset;

function ConsoleCliLines({ motionEnabled }: { motionEnabled: boolean }) {
  if (!motionEnabled) return <ConsoleCliStatic />;
  return <ConsoleCliTyped />;
}

function ConsoleCliStatic() {
  return (
    <div className="console-lines">
      {cliConsoleScript.map((line, index) => (
        <p key={index} className={line.kind === "dim" ? "dim" : line.kind === "accent" ? "accent" : undefined}>
          {line.kind === "command" ? <><i>→</i> {line.text}</> : line.text}
        </p>
      ))}
      <span className="console-cursor" />
    </div>
  );
}

function ConsoleCliTyped() {
  const [typed, setTyped] = useState(0);

  useEffect(() => {
    let current = 0;
    let rafId = 0;
    let lastTime = 0;
    const step = (time: number) => {
      if (!lastTime) lastTime = time;
      // ~24ms per char ≈ 42 chars/sec → delta / 24
      const elapsed = time - lastTime;
      const advance = Math.floor(elapsed / 24);
      if (advance > 0) {
        current = Math.min(cliTotalChars, current + advance);
        setTyped(current);
        lastTime = time;
      }
      if (current < cliTotalChars) {
        rafId = window.requestAnimationFrame(step);
      }
    };
    rafId = window.requestAnimationFrame(step);
    return () => window.cancelAnimationFrame(rafId);
  }, []);

  return (
    <div className="console-lines">
      {cliConsoleScript.map((line, index) => {
        const visibleChars = Math.max(0, Math.min(line.text.length, typed - line.start));
        const pending = visibleChars <= 0;
        const className = line.kind === "dim" ? "dim" : line.kind === "accent" ? "accent" : undefined;
        return (
          <p key={index} className={className} style={pending ? { visibility: "hidden" } : undefined}>
            {line.kind === "command" ? <><i>→</i> </> : null}
            {line.text.slice(0, visibleChars)}
          </p>
        );
      })}
      <span className="console-cursor" />
    </div>
  );
}

