import { AnimatePresence, LazyMotion, domAnimation, m } from "motion/react";
import { BookOpenText, Braces, ExternalLink, GitBranch, Menu, MonitorSmartphone, Search, X } from "lucide-react";
import { lazy, Suspense, useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { Navigate, NavLink, Route, Routes, useLocation } from "react-router-dom";
import { SettingsControls } from "./components/SettingsControls";
import { usePreferences } from "./hooks/usePreferences";
import { useScrollReveal } from "./hooks/useScrollReveal";
import { MainSitePage } from "./pages/MainSitePage";
import { OverviewPage } from "./pages/OverviewPage";
import { detectExperienceMode } from "./pages/experience/detectExperienceMode";

const ExperiencePage = lazy(() => import("./pages/ExperiencePage").then((module) => ({ default: module.ExperiencePage })));
const ExperiencePage3D = lazy(() => import("./pages/experience3d/ExperiencePage3D").then((module) => ({ default: module.ExperiencePage3D })));
const DroneShowPage = lazy(() => import("./pages/droneShow/DroneShowPage").then((module) => ({ default: module.DroneShowPage })));
const PianoPage = lazy(() => import("./pages/PianoPage").then((module) => ({ default: module.PianoPage })));
const SamplesPage = lazy(() => import("./pages/SamplesPage").then((module) => ({ default: module.SamplesPage })));
const CommandsPage = lazy(() => import("./pages/CommandsPage").then((module) => ({ default: module.CommandsPage })));
const GuiPage = lazy(() => import("./pages/GuiPage").then((module) => ({ default: module.GuiPage })));
const ParticleField = lazy(() => import("./components/ParticleField").then((module) => ({ default: module.ParticleField })));
const CommandPalette = lazy(() => import("./components/CommandPalette").then((module) => ({ default: module.CommandPalette })));

const navItems = [
  { path: "/docs", labelKey: "nav.overview", caption: "Overview", icon: BookOpenText },
  { path: "/docs/commands", labelKey: "nav.commands", caption: "CLI Atlas", icon: Braces },
  { path: "/docs/gui", labelKey: "nav.gui", caption: "GUI Surface", icon: MonitorSmartphone },
];

function isDocsPath(pathname: string) {
  return pathname.startsWith("/docs") || pathname === "/commands" || pathname === "/gui";
}

export default function App() {
  const { t } = useTranslation();
  const { motionEnabled } = usePreferences();
  const [menuOpen, setMenuOpen] = useState(false);
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [paletteLoaded, setPaletteLoaded] = useState(false);
  const location = useLocation();
  const docsMode = isDocsPath(location.pathname);
  const experienceMode = location.pathname === "/experience";
  const droneShowMode = location.pathname === "/drone-show";
  const pianoMode = location.pathname === "/piano";
  const samplesMode = location.pathname === "/samples";
  // 进入体验馆路由时探测一次渲染模式（2D/3D）；结果随路由参数缓存，避免重复创建 WebGL 探测上下文
  const experienceRenderer = useMemo(
    () => (experienceMode ? detectExperienceMode() : "2d"),
    [experienceMode, location.search, location.hash],
  );
  const activeItem = useMemo(() => navItems.find((item) => item.path === location.pathname) ?? navItems[0], [location.pathname]);
  useScrollReveal(location.pathname, motionEnabled);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: "auto" });
  }, [location.pathname]);

  useEffect(() => {
    const handleKey = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setPaletteLoaded(true);
        setPaletteOpen((value) => !value);
      }
      if (event.key === "Escape") setPaletteOpen(false);
    };
    window.addEventListener("keydown", handleKey);
    return () => window.removeEventListener("keydown", handleKey);
  }, []);

  const openPalette = () => {
    setPaletteLoaded(true);
    setPaletteOpen(true);
  };

  return (
    <div className={`site-shell ${droneShowMode ? "site-shell--drone" : pianoMode ? "site-shell--piano" : samplesMode ? "site-shell--samples" : docsMode ? "site-shell--docs" : experienceMode ? "site-shell--experience" : "site-shell--main"}`}>
      {!experienceMode && !droneShowMode && !pianoMode && !samplesMode ? <>
        <Suspense fallback={null}><ParticleField /></Suspense>
        <div className="scan-layer" aria-hidden="true" />
      </> : null}
      {droneShowMode ? (
        <Suspense fallback={<div className="drone-loading" aria-label="Loading"><span /><span /><span /></div>}>
          <DroneShowPage />
        </Suspense>
      ) : pianoMode ? (
        <Suspense fallback={<div className="route-loading" aria-label="Loading"><span /><span /><span /></div>}>
          <PianoPage />
        </Suspense>
      ) : samplesMode ? (
        <Suspense fallback={<div className="route-loading" aria-label="Loading"><span /><span /><span /></div>}>
          <SamplesPage />
        </Suspense>
      ) : experienceMode ? <Suspense fallback={<div className="experience-loading" aria-label="Loading"><span /><span /><span /></div>}>{experienceRenderer === "3d" ? <ExperiencePage3D /> : <ExperiencePage />}</Suspense> : docsMode ? (
        <DocsShell
          activeItem={activeItem}
          menuOpen={menuOpen}
          setMenuOpen={setMenuOpen}
          openPalette={openPalette}
          motionEnabled={motionEnabled}
          t={t}
        />
      ) : <MainSitePage />}
      {!experienceMode && !droneShowMode && !pianoMode && !samplesMode && paletteLoaded ? <Suspense fallback={null}><CommandPalette open={paletteOpen} onClose={() => setPaletteOpen(false)} /></Suspense> : null}
    </div>
  );
}

type DocsShellProps = {
  activeItem: (typeof navItems)[number];
  menuOpen: boolean;
  setMenuOpen: (value: boolean) => void;
  openPalette: () => void;
  motionEnabled: boolean;
  t: (key: string, options?: Record<string, unknown>) => string;
};

function DocsShell({ activeItem, menuOpen, setMenuOpen, openPalette, motionEnabled, t }: DocsShellProps) {
  const location = useLocation();
  return (
    <>
      <aside className={`sidebar ${menuOpen ? "sidebar--open" : ""}`}>
        <div className="brand-lockup">
          <img src="./branding/hongyunx-mark.svg" alt={t("brand.name")} />
          <div><strong>{t("brand.name")}</strong><span>DOCUMENTATION</span></div>
          <button className="icon-button sidebar-close" type="button" onClick={() => setMenuOpen(false)} aria-label={t("common.closeMenu")} title={t("common.closeMenu")}><X size={18} /></button>
        </div>
        <div className="sidebar-label">{t("sidebar.directories").toUpperCase()}</div>
        <nav className="side-nav" aria-label={t("sidebar.directories")}>
          {navItems.map((item, index) => {
            const Icon = item.icon;
            return (
              <NavLink key={item.path} to={item.path} end={item.path === "/docs"} onClick={() => setMenuOpen(false)}>
                <span className="nav-number">0{index + 1}</span>
                <Icon size={17} />
                <span><b>{t(item.labelKey)}</b><small>{item.caption}</small></span>
              </NavLink>
            );
          })}
        </nav>
        <div className="sidebar-scope">
          <span>{t("sidebar.scope").toUpperCase()}</span>
          <p>{t("sidebar.localDelivery")}</p>
          <i><b /> {t("sidebar.repository")}</i>
        </div>
      </aside>

      {menuOpen ? <button className="menu-scrim" aria-label={t("common.closeMenu")} type="button" onClick={() => setMenuOpen(false)} /> : null}

      <div className="site-main">
        <header className="topbar">
          <div className="topbar__route">
            <button className="icon-button menu-button" type="button" onClick={() => setMenuOpen(true)} aria-label={t("common.openMenu")} title={t("common.openMenu")}><Menu size={19} /></button>
            <NavLink className="topbar__home" to="/">HongyunX</NavLink><i>/</i><strong>{activeItem.caption.toLowerCase().replace(" ", "-")}</strong>
          </div>
          <div className="topbar__actions">
            <button className="search-trigger" type="button" onClick={openPalette} aria-label={t("common.search")} title={t("common.search")}><Search size={15} /><span>{t("common.search")}</span><kbd>Ctrl K</kbd></button>
            <SettingsControls />
            <a className="icon-button repo-link" href="https://github.com/qiekuo/HongyunX-Agent" target="_blank" rel="noreferrer" aria-label={t("common.github")} title="GitHub"><GitBranch size={18} /></a>
            <a className="topbar-docs" href="https://github.com/qiekuo/HongyunX-Agent/blob/main/docs/USER_GUIDE.md" target="_blank" rel="noreferrer">{t("common.userGuide")} <ExternalLink size={13} /></a>
          </div>
        </header>

        <main className="content-shell">
          <LazyMotion features={domAnimation}>
            <AnimatePresence mode="wait" initial={false}>
              <m.div
                className="route-frame"
                key={location.pathname}
                initial={motionEnabled ? { opacity: 0, y: 10 } : false}
                animate={{ opacity: 1, y: 0 }}
                exit={motionEnabled ? { opacity: 0, y: -7 } : undefined}
                transition={{ duration: 0.24, ease: "easeOut" }}
              >
                <Suspense fallback={<div className="route-loading" aria-label="Loading"><span /><span /><span /></div>}>
                  <Routes location={location}>
                    <Route path="/docs" element={<OverviewPage />} />
                    <Route path="/docs/commands" element={<CommandsPage />} />
                    <Route path="/docs/gui" element={<GuiPage />} />
                    <Route path="/commands" element={<Navigate to="/docs/commands" replace />} />
                    <Route path="/gui" element={<Navigate to="/docs/gui" replace />} />
                    <Route path="*" element={<Navigate to="/docs" replace />} />
                  </Routes>
                </Suspense>
              </m.div>
            </AnimatePresence>
          </LazyMotion>
        </main>
        <footer className="site-footer"><span>{t("brand.name")} / Documentation</span><span>{t("footer.static")}</span></footer>
      </div>
    </>
  );
}
