import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
import i18n from "../i18n";
import { PreferencesContext, type AppLanguage, type ResolvedTheme, type ThemeMode } from "./preferences-context";

const THEME_KEY = "hongyunx.atlas.theme";
const LANGUAGE_KEY = "hongyunx.atlas.language";
const MOTION_KEY = "hongyunx.atlas.motion";

function getStoredTheme(): ThemeMode {
  const value = localStorage.getItem(THEME_KEY);
  return value === "light" || value === "dark" || value === "system" ? value : "system";
}

function resolveTheme(mode: ThemeMode): ResolvedTheme {
  if (mode !== "system") return mode;
  return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

function getStoredLanguage(): AppLanguage {
  const value = localStorage.getItem(LANGUAGE_KEY);
  if (value === "zh-CN" || value === "en") return value;
  return navigator.language.toLowerCase().startsWith("zh") ? "zh-CN" : "en";
}

function getStoredMotion() {
  const value = localStorage.getItem(MOTION_KEY);
  if (value === "on" || value === "off") return value === "on";
  return !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function PreferencesProvider({ children }: { children: ReactNode }) {
  const [themeMode, setThemeModeState] = useState<ThemeMode>(getStoredTheme);
  const [resolvedTheme, setResolvedTheme] = useState<ResolvedTheme>(() => resolveTheme(getStoredTheme()));
  const [language, setLanguageState] = useState<AppLanguage>(getStoredLanguage);
  const [motionEnabled, setMotionEnabledState] = useState(getStoredMotion);

  const applyResolvedTheme = useCallback((theme: ResolvedTheme, animate: boolean) => {
    const root = document.documentElement;
    if (animate && root.dataset.motion !== "off") root.dataset.themeTransition = "true";
    root.dataset.theme = theme;
    document.querySelector('meta[name="theme-color"]')?.setAttribute("content", theme === "dark" ? "#070b0a" : "#f4f8f7");
    setResolvedTheme(theme);
    if (animate) window.setTimeout(() => delete root.dataset.themeTransition, 420);
  }, []);

  const setThemeMode = useCallback((mode: ThemeMode) => {
    localStorage.setItem(THEME_KEY, mode);
    document.documentElement.dataset.themeMode = mode;
    setThemeModeState(mode);
    applyResolvedTheme(resolveTheme(mode), true);
  }, [applyResolvedTheme]);

  const setLanguage = useCallback((nextLanguage: AppLanguage) => {
    localStorage.setItem(LANGUAGE_KEY, nextLanguage);
    document.documentElement.lang = nextLanguage;
    document.documentElement.dataset.language = nextLanguage;
    setLanguageState(nextLanguage);
    void i18n.changeLanguage(nextLanguage);
  }, []);

  const setMotionEnabled = useCallback((enabled: boolean) => {
    localStorage.setItem(MOTION_KEY, enabled ? "on" : "off");
    document.documentElement.dataset.motion = enabled ? "on" : "off";
    setMotionEnabledState(enabled);
  }, []);

  useEffect(() => {
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    const handleChange = () => {
      if (themeMode === "system") applyResolvedTheme(media.matches ? "dark" : "light", true);
    };
    media.addEventListener("change", handleChange);
    return () => media.removeEventListener("change", handleChange);
  }, [applyResolvedTheme, themeMode]);

  useEffect(() => {
    document.documentElement.dataset.themeMode = themeMode;
    document.documentElement.dataset.motion = motionEnabled ? "on" : "off";
    document.documentElement.dataset.language = language;
    document.documentElement.lang = language;
  }, [language, motionEnabled, themeMode]);

  const value = useMemo(() => ({
    themeMode,
    resolvedTheme,
    language,
    motionEnabled,
    setThemeMode,
    setLanguage,
    setMotionEnabled,
  }), [language, motionEnabled, resolvedTheme, setLanguage, setMotionEnabled, setThemeMode, themeMode]);

  return <PreferencesContext.Provider value={value}>{children}</PreferencesContext.Provider>;
}
