// 体验馆渲染模式探测：返回 "2d" | "3d"。
// 规则：
//  - ?mode=2d / ?mode=3d 强制覆盖（含 hash 路由中的查询串）
//  - 无 WebGL、粗指针（触屏）、窄屏、低核数 → 2D
//  - 其余 → 3D

function hasWebGL(): boolean {
  try {
    const canvas = document.createElement("canvas");
    const gl = canvas.getContext("webgl2") ?? canvas.getContext("webgl");
    return gl !== null;
  } catch {
    return false;
  }
}

function forcedMode(): "2d" | "3d" | null {
  const search = window.location.search;
  const hashQuery = window.location.hash.includes("?") ? window.location.hash.slice(window.location.hash.indexOf("?")) : "";
  for (const source of [search, hashQuery]) {
    const value = new URLSearchParams(source).get("mode");
    if (value === "2d" || value === "3d") return value;
  }
  return null;
}

export function detectExperienceMode(): "2d" | "3d" {
  const forced = forcedMode();
  if (forced) return forced;
  if (typeof window === "undefined") return "2d";
  if (!hasWebGL()) return "2d";
  if (window.matchMedia("(pointer: coarse)").matches && window.innerWidth < 1024) return "2d";
  if (window.innerWidth < 768) return "2d";
  const cores = navigator.hardwareConcurrency ?? 8;
  if (cores < 4) return "2d";
  return "3d";
}
